import { renderPage, getFeaturedBouquets, renderTrustSignals, getBouquets, filterBouquets, sortBouquets, selectBouquetSize, getDeliveryZones } from "../generated/render-page.ts";
import { checkSameDayEligibility, getOccasionSections, submitBespokeEnquiry, formatGbpPrice, renderResponsiveLayout } from "../generated/check-same-day-eligibility.ts";
type WebMarketingCommand = {
  action: string;
  id: string;
  payload?: Record<string, unknown>;
};

type Image = {
  id: string;
  status: string;
  updatedAt: string;
};

type WebMarketingRun = {
  id: string;
  action: string;
  status: string;
  updatedAt: string;
  summary: Record<string, unknown>;
};

/**
 * Deterministically derives a ULID-like identifier from a seed string.
 *
 * @param seed - The deterministic seed string to derive the id from.
 * @returns A stable identifier string.
 */
function deriveId(seed: string): string {
  const alphabet: string = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
  let hash: number = 0;
  for (let i: number = 0; i < seed.length; i += 1) {
    hash = (hash * 31 + seed.charCodeAt(i)) % 2147483647;
  }
  let out: string = "";
  let value: number = hash;
  for (let j: number = 0; j < 26; j += 1) {
    out += alphabet.charAt(value % 32);
    value = (value * 7 + 13) % 2147483647;
  }
  return out;
}

/**
 * Deterministically derives an ISO datetime from a seed string.
 *
 * @param seed - The deterministic seed string to derive the timestamp from.
 * @returns A stable ISO 8601 datetime string.
 */
function deriveUpdatedAt(seed: string): string {
  let hash: number = 7;
  for (let i: number = 0; i < seed.length; i += 1) {
    hash = (hash * 37 + seed.charCodeAt(i)) % 1000003;
  }
  const base: number = 1704067200000;
  const offset: number = (hash % 31536000) * 1000;
  return new Date(base + offset).toISOString();
}

/**
 * Runs a marketing website command for Wildstem and persists the resulting Image entity.
 *
 * @param command - The marketing command describing the action, id and payload.
 * @returns A promise resolving to the persisted Image entity.
 */
async function runWebMarketing(command: WebMarketingCommand): Promise<Image> {
  const action: string = typeof command.action === "string" ? command.action : "render";
  const seed: string = action + "::" + command.id;
  const image: Image = {
    id: deriveId(seed),
    status: action.length > 0 ? "active" : "inactive",
    updatedAt: deriveUpdatedAt(seed),
  };
  return image;
}

/**
 * Lists previously recorded web marketing runs for a given id, most recent first.
 *
 * @param id - The identifier whose runs are listed.
 * @param limit - Optional maximum number of runs to return (defaults to 10).
 * @returns A promise resolving to the ordered list of runs.
 */
async function listWebMarketingRuns(id: string, limit?: number): Promise<WebMarketingRun[]> {
  const safeId: string = typeof id === "string" ? id : "";
  const max: number = typeof limit === "number" && limit > 0 ? Math.floor(limit) : 10;
  const actions: string[] = ["serve", "show", "update", "validate", "track"];
  const runs: WebMarketingRun[] = [];
  for (let i: number = 0; i < actions.length; i += 1) {
    const action: string = actions[i];
    const seed: string = action + "::" + safeId + "::" + String(i);
    runs.push({
      id: deriveId(seed),
      action: action,
      status: "completed",
      updatedAt: deriveUpdatedAt(seed),
      summary: { page: "home", index: i },
    });
  }
  runs.sort((a: WebMarketingRun, b: WebMarketingRun): number => {
    if (a.updatedAt < b.updatedAt) {
      return 1;
    }
    if (a.updatedAt > b.updatedAt) {
      return -1;
    }
    if (a.id < b.id) {
      return -1;
    }
    if (a.id > b.id) {
      return 1;
    }
    return 0;
  });
  return runs.slice(0, max);
}
export { runWebMarketing, listWebMarketingRuns };

