/**
 * Normalizes a postcode for zone matching by trimming, upper-casing and
 * removing spaces.
 *
 * @param postcode - the raw postcode string
 * @returns the normalized postcode string
 */
function normalizeWildstemPostcode(postcode: string): string {
  if (typeof postcode !== 'string') {
    return '';
  }
  return postcode.trim().toUpperCase().split(' ').join('');
}

/**
 * Parses a HH:MM time string into minutes since midnight.
 *
 * @param time - the time string to parse
 * @returns minutes since midnight, or -1 when unparseable
 */
function parseWildstemTime(time: string): number {
  if (typeof time !== 'string') {
    return -1;
  }
  var parts: string[] = time.trim().split(':');
  if (parts.length !== 2) {
    return -1;
  }
  var hours: number = Number(parts[0]);
  var minutes: number = Number(parts[1]);
  if (!isFinite(hours) || !isFinite(minutes)) {
    return -1;
  }
  if (hours < 0 || hours > 23 || minutes < 0 || minutes > 59) {
    return -1;
  }
  return hours * 60 + minutes;
}

