const PAGE_TITLES: Record<string, string> = {
  home: 'Wildstem Florist — Seasonal Blooms, Same-Day Delivery',
  bouquets: 'Bouquets — Wildstem Florist',
  delivery: 'Delivery — Wildstem Florist',
  occasions: 'Occasions — Wildstem Florist',
  contact: 'Bespoke Enquiry — Wildstem Florist',
};

const PAGE_HEADINGS: Record<string, string> = {
  home: 'Fresh flowers, arranged by hand',
  bouquets: 'Our bouquets',
  delivery: 'Delivery zones and cutoffs',
  occasions: 'Flowers for every occasion',
  contact: 'Send a bespoke enquiry',
};

const PAGE_SECTIONS: Record<string, string[]> = {
  home: ['Hero', 'Same-day delivery banner', 'Featured bouquets', 'Trust signals'],
  bouquets: ['Catalogue grid', 'Occasion filter', 'Price band filter', 'Sort control', 'Empty state'],
  delivery: ['Delivery zones', 'Per-zone fees and cutoffs', 'Same-day eligibility checker'],
  occasions: ['Birthday', 'Anniversary', 'New Baby', 'Sympathy', 'Thank You'],
  contact: ['Bespoke order form', 'Field validation', 'Confirmation reference'],
};

/**
 * Resolve the content for one of the site's five pages.
 * @param pageId - the identifier of the page to resolve
 * @returns the page content with title, heading, sections and same-day banner
 */
// req-1
// req-2
function renderPage(pageId: PageId): PageContent {
  const key: string = String(pageId);
  const title: string = key in PAGE_TITLES ? PAGE_TITLES[key] : PAGE_TITLES.home;
  const heading: string = key in PAGE_HEADINGS ? PAGE_HEADINGS[key] : PAGE_HEADINGS.home;
  const sections: string[] = key in PAGE_SECTIONS ? PAGE_SECTIONS[key].slice() : PAGE_SECTIONS.home.slice();
  return {
    pageId: pageId,
    title: title,
    heading: heading,
    sections: sections,
    sameDayBanner: SAME_DAY_BANNER,
  };
}

/**
 * Return the first `count` featured bouquets from the catalogue.
 * @param count - number of featured bouquets to return
 * @returns the featured bouquet list
 */
// req-2
function getFeaturedBouquets(count: number): Bouquet[] {
  const safeCount: number = count > 0 ? Math.floor(count) : 0;
  const result: Bouquet[] = [];
  let index: number = 0;
  while (index < safeCount && index < BOUQUETS.length) {
    result.push(BOUQUETS[index]);
    index += 1;
  }
  return result;
}

/**
 * Return the Home page trust signals.
 * @returns years in business and review stars
 */
// req-2
function renderTrustSignals(): TrustSignals {
  return {
    yearsInBusiness: 14,
    reviewStars: 4.9,
    reviewCount: 1268,
  };
}

/**
 * Return the full bouquet catalogue.
 * @returns every bouquet in the catalogue
 */
// req-3
function getBouquets(): Bouquet[] {
  return BOUQUETS.slice();
}

/**
 * Filter bouquets by occasion tag and price band, both applied at once.
 * @param bouquets - the bouquet list to filter
 * @param occasion - the selected occasion tag, or null for all occasions
 * @param priceBand - the selected price band with inclusive min and max
 * @returns bouquets matching both the occasion and the price band
 */
// req-4
function filterBouquets(bouquets: Bouquet[], occasion: OccasionTag | null, priceBand: PriceBand): Bouquet[] {
  const source: Bouquet[] = Array.isArray(bouquets) ? bouquets : [];
  const filtered: Bouquet[] = [];
  let index: number = 0;
  while (index < source.length) {
    const bouquet: Bouquet = source[index];
    const baseAmount: number = bouquet.basePrice.amount;
    const occasionOk: boolean = occasion === null || bouquet.occasions.indexOf(occasion) !== -1;
    const priceOk: boolean = baseAmount >= priceBand.min && baseAmount <= priceBand.max;
    if (occasionOk && priceOk) {
      filtered.push(bouquet);
    }
    index += 1;
  }
  return filtered;
}

/**
 * Sort bouquets by base price in the requested direction, deterministically.
 * @param bouquets - the bouquet list to sort
 * @param direction - 'asc' for cheapest first, 'desc' for most expensive first
 * @returns a new array sorted by base price then id
 */
// req-4
function sortBouquets(bouquets: Bouquet[], direction: 'asc' | 'desc'): Bouquet[] {
  const source: Bouquet[] = Array.isArray(bouquets) ? bouquets.slice() : [];
  source.sort((a: Bouquet, b: Bouquet): number => {
    const diff: number = a.basePrice.amount - b.basePrice.amount;
    if (diff !== 0) {
      return direction === 'asc' ? diff : -diff;
    }
    if (a.id < b.id) {
      return -1;
    }
    if (a.id > b.id) {
      return 1;
    }
    return 0;
  });
  return source;
}

/**
 * Select a size for a bouquet and return the id, size and per-size price.
 * @param bouquet - the bouquet being configured
 * @param size - the chosen size option
 * @returns the bouquet id, chosen size and matching GBP price
 */
// req-9
function selectBouquetSize(bouquet: Bouquet, size: BouquetSize): { bouquetId: string; size: BouquetSize; price: Money } {
  let selected: SizePrice | null = null;
  let index: number = 0;
  while (index < bouquet.sizePrices.length) {
    const entry: SizePrice = bouquet.sizePrices[index];
    if (entry.size === size) {
      selected = entry;
      break;
    }
    index += 1;
  }
  if (selected === null) {
    selected = {
      size: 'Classic',
      price: bouquet.basePrice,
    };
  }
  return {
    bouquetId: bouquet.id,
    size: selected.size,
    price: selected.price,
  };
}

/**
 * Return the served delivery zones with prefixes, fees and cutoff times.
 * @returns every delivery zone
 */
// req-6
function getDeliveryZones(): DeliveryZone[] {
  return DELIVERY_ZONES.slice();
}
export { renderPage, getFeaturedBouquets, renderTrustSignals, getBouquets, filterBouquets, sortBouquets, selectBouquetSize, getDeliveryZones };

