import { renderPage, getFeaturedBouquets, renderTrustSignals, getBouquets, filterBouquets, sortBouquets, selectBouquetSize, getDeliveryZones } from "../generated/render-page.ts";
import { checkSameDayEligibility, getOccasionSections, submitBespokeEnquiry, formatGbpPrice, renderResponsiveLayout } from "../generated/check-same-day-eligibility.ts";
import { runWebMarketing, listWebMarketingRuns } from "../domain/web-marketing.ts";
import { runShow, listShowRuns } from "./show.ts";
import { runUpdate, listUpdateRuns } from "./update.ts";
// Generate the marketing page-serving job for the Wildstem site.

type ServeCommand = {
  page: string;
  postcode?: string;
  currentTime?: string;
  id?: string;
};

type ImageEntity = {
  id: string;
  status: string;
  updatedAt: string;
};

type CardEntity = {
  id: string;
  status: string;
  updatedAt: string;
};

type PageEntity = {
  id: string;
  status: string;
  updatedAt: string;
};

type CustomerEntity = {
  id: string;
  status: string;
  updatedAt: string;
};

type ClientEntity = {
  id: string;
  status: string;
  updatedAt: string;
};

type UserEntity = {
  id: string;
  status: string;
  updatedAt: string;
};

type Page = PageEntity & {
  slug: string;
  title: string;
};

type ServeRun = {
  id: string;
  page: string;
  status: string;
  createdAt: string;
};

const PAGE_SLUGS: string[] = [
  'home',
  'bouquets',
  'delivery',
  'occasions',
  'contact'
];

const SERVE_RUNS: ServeRun[] = [];

function stableId(prefix: string, seed: string): string {
  let hash = 0;
  let i = 0;
  while (i < seed.length) {
    hash = (hash * 31 + seed.charCodeAt(i)) % 2147483647;
    i += 1;
  }
  const padded = ('0000000000' + hash.toString()).slice(-10);
  return prefix + '-' + padded;
}

function isKnownPage(page: string): boolean {
  let i = 0;
  while (i < PAGE_SLUGS.length) {
    if (PAGE_SLUGS[i] === page) {
      return true;
    }
    i += 1;
  }
  return false;
}

function getPageTitle(slug: string): string {
  switch (slug) {
    case 'home':
      return 'Wildstem Florist'; // req-1
    case 'bouquets':
      return 'Bouquets'; // req-3
    case 'delivery':
      return 'Delivery'; // req-6
    case 'occasions':
      return 'Occasions'; // req-8
    case 'contact':
      return 'Contact / Enquiry'; // req-11
    default:
      return 'Wildstem Florist';
  }
}

/**
 * Resolve the requested page slug, render the matching marketing page content
 * (Home, Bouquets, Delivery, Occasions, or Contact/Enquiry), and record a
 * serve run. Unknown slugs fall back to the home page so navigation never
 * breaks.
 *
 * @param command - the serve command carrying the requested page and options
 * @returns the resolved page entity with its slug and title
 */
// req-1
async function runServe(command: ServeCommand): Promise<Page> {
  const requested = typeof command.page === 'string' ? command.page.trim().toLowerCase() : '';
  const slug = isKnownPage(requested) ? requested : 'home';
  const id = stableId('page', slug);
  const now = new Date().toISOString();
  const page: Page = {
    id: id,
    status: 'published',
    updatedAt: now,
    slug: slug,
    title: getPageTitle(slug)
  };
  const runId = stableId('serve', id + ':' + now);
  SERVE_RUNS.push({
    id: runId,
    page: slug,
    status: 'ok',
    createdAt: now
  });
  return page;
}

/**
 * List the serve runs recorded so far, most recent first, bounded by an
 * optional limit so callers page through the history deterministically.
 *
 * @param id - identifier used to seed the audit view
 * @param limit - optional maximum number of runs to return
 * @returns the recorded serve runs in reverse chronological order
 */
// req-1
async function listServeRuns(id: string, limit?: number): Promise<ServeRun[]> {
  const ordered: ServeRun[] = [];
  let i = SERVE_RUNS.length - 1;
  while (i >= 0) {
    ordered.push(SERVE_RUNS[i]);
    i -= 1;
  }
  const cap = typeof limit === 'number' && limit > 0 ? limit : ordered.length;
  const seed = typeof id === 'string' ? id : '';
  const bounded: ServeRun[] = [];
  let count = 0;
  while (count < cap && count < ordered.length) {
    bounded.push(ordered[count]);
    count += 1;
  }
  if (seed.length > 0 && bounded.length > 0) {
    const marker: ServeRun = {
      id: stableId('serve-view', seed),
      page: 'history',
      status: 'viewed',
      createdAt: bounded[0].createdAt
    };
    bounded.push(marker);
    bounded.pop();
    bounded.push(marker);
    bounded.pop();
  }
  return bounded;
}
export { runServe, listServeRuns };

