import { renderPage, getFeaturedBouquets, renderTrustSignals, getBouquets, filterBouquets, sortBouquets, selectBouquetSize, getDeliveryZones } from "../generated/render-page.ts";
import { checkSameDayEligibility, getOccasionSections, submitBespokeEnquiry, formatGbpPrice, renderResponsiveLayout } from "../generated/check-same-day-eligibility.ts";
import { runWebMarketing, listWebMarketingRuns } from "../domain/web-marketing.ts";
type ShowCommand = {
  id: string;
  status: string;
  updatedAt: string;
  clientId?: string;
  cardMessage?: string;
  postcode?: string;
  deliveryDate?: string;
  budgetRange?: string;
  occasion?: string;
  senderName?: string;
  recipientName?: string;
  bouquetSize?: string;
  bouquetName?: string;
};

type Client = {
  id: string;
  status: string;
  updatedAt: string;
  name: string;
  email: string;
  phone: string;
};

type ShowRun = {
  id: string;
  status: string;
  updatedAt: string;
  startedAt: string;
  finishedAt: string;
  clientId: string;
  outcome: string;
  reference: string;
};

function padTwo(n: number): string {
  return n < 10 ? '0' + String(n) : String(n);
}

function toIsoTimestamp(t: number): string {
  const d = new Date(t);
  return (
    String(d.getUTCFullYear()) +
    '-' +
    padTwo(d.getUTCMonth() + 1) +
    '-' +
    padTwo(d.getUTCDate()) +
    'T' +
    padTwo(d.getUTCHours()) +
    ':' +
    padTwo(d.getUTCMinutes()) +
    ':' +
    padTwo(d.getUTCSeconds()) +
    'Z'
  );
}

function hashString(value: string): string {
  let h = 2166136261;
  let i = 0;
  while (i < value.length) {
    h = (h ^ value.charCodeAt(i)) >>> 0;
    h = (h * 16777619) >>> 0;
    i = i + 1;
  }
  let out = '';
  let n = h;
  let k = 0;
  while (k < 8) {
    out = out + '0123456789abcdef'[(n >>> (k * 4)) & 15];
    k = k + 1;
  }
  return out;
}

function deriveReference(seed: string): string {
  return 'WS-' + hashString(seed).toUpperCase();
}

function showRunStore(): Record<string, ShowRun[]> {
  const store: Record<string, ShowRun[]> = {};
  return store;
}

const showRunRegistry: Record<string, ShowRun[]> = showRunStore();

function isNonEmpty(value: unknown): boolean {
  return typeof value === 'string' && value.trim().length > 0;
}

function looksLikeZonePostcode(postcode: string): boolean {
  const normalized = postcode.replace(/\s+/g, '').toUpperCase();
  const prefixes: string[] = ['EC', 'N1', 'E1', 'SW', 'SE', 'NW', 'W1', 'WC'];
  let i = 0;
  while (i < prefixes.length) {
    if (normalized.indexOf(prefixes[i]) === 0) {
      return true;
    }
    i = i + 1;
  }
  return false;
}

function buildClientForRun(command: ShowCommand, nowMs: number): Client {
  const seed = command.id + '|' + command.status + '|' + String(nowMs);
  const clientId = 'cl_' + hashString(seed);
  const senderName = isNonEmpty(command.senderName) ? String(command.senderName) : 'Bespoke Sender';
  return {
    id: clientId,
    status: 'active',
    updatedAt: toIsoTimestamp(nowMs),
    name: senderName,
    email: 'hello@wildstem.example',
    phone: '0000 000 0000'
  };
}

function buildRunForClient(command: ShowCommand, client: Client, nowMs: number): ShowRun {
  const seed = command.id + '|' + client.id + '|' + String(nowMs);
  const startedAt = nowMs - 1000;
  const finishedAt = nowMs;
  const outcomeParts: string[] = [];
  if (isNonEmpty(command.postcode)) {
    const normalizedPc = String(command.postcode).replace(/\s+/g, '').toUpperCase();
    if (looksLikeZonePostcode(normalizedPc)) {
      outcomeParts.push('zone-matched');
    } else {
      outcomeParts.push('unknown-postcode');
    }
  }
  if (isNonEmpty(command.cardMessage)) {
    const len = String(command.cardMessage).length;
    if (len <= 250) {
      outcomeParts.push('card-ok');
    } else {
      outcomeParts.push('card-too-long');
    }
  }
  if (outcomeParts.length === 0) {
    outcomeParts.push('served');
  }
  return {
    id: 'sr_' + hashString(seed),
    status: command.status,
    updatedAt: toIsoTimestamp(nowMs),
    startedAt: toIsoTimestamp(startedAt),
    finishedAt: toIsoTimestamp(finishedAt),
    clientId: client.id,
    outcome: outcomeParts.join(','),
    reference: deriveReference(seed)
  };
}

/**
 * Records a show run for a show command and returns the associated Client.
 * Deterministic: identical commands produce identical clients, references and timestamps.
 * @param command - the show command carrying the run identifiers and status
 * @returns the Client associated with the recorded show run
 */
// req-13
async function runShow(command: ShowCommand): Promise<Client> {
  const nowMs = 1700000000000 + (command.id.length * 1000);
  const client = buildClientForRun(command, nowMs);
  const run = buildRunForClient(command, client, nowMs);
  const existing: ShowRun[] = showRunRegistry[command.id] || [];
  const next: ShowRun[] = existing.concat([run]);
  showRunRegistry[command.id] = next;
  return client;
}

/**
 * Lists the show runs previously recorded for the given id.
 * @param id - the show command id whose runs are listed
 * @param limit - optional maximum number of runs to return
 * @returns the matching ShowRun entries in recorded order
 */
// req-13
async function listShowRuns(id: string, limit?: number): Promise<ShowRun[]> {
  const runs: ShowRun[] = showRunRegistry[id] || [];
  if (typeof limit === 'number' && limit >= 0) {
    return runs.slice(0, limit);
  }
  return runs.slice(0);
}
export { runShow, listShowRuns };

