type TrackCommand = {
  id: string;
  status?: string;
  updatedAt?: string;
};

type Card = {
  id: string;
  status: string;
  updatedAt: string;
};

type TrackRun = {
  id: string;
  commandId: string;
  status: string;
  cardId: string;
  updatedAt: string;
};

const __trackRuns: TrackRun[] = [];

function __normalizeCommandId(id: string): string {
  return typeof id === 'string' && id.length > 0 ? id : 'unknown';
}

function __deriveTimestamp(seed: string, offset: number): string {
  let hash: number = 0;
  for (let i = 0; i < seed.length; i++) {
    hash = (hash * 31 + seed.charCodeAt(i)) % 100000000;
  }
  const base: number = 1700000000000;
  const value: number = base + (hash % 1000000) * 1000 + offset;
  return new Date(value).toISOString();
}

/**
 * Run a tracking command for the marketing site's Card entity.
 *
 * Derives a deterministic Card record from the supplied command so two
 * identical runs produce identical output. The resulting Card is recorded
 * in the trailing run history so listTrackRuns can return stable results.
 *
 * @param command - the track command carrying the card identifier and status
 * @returns a promise resolving to the tracked Card
 */
// req-13
// req-2
async function runTrack(command: TrackCommand): Promise<Card> {
  const safeCommand: TrackCommand = command !== null && typeof command === 'object' ? command : { id: '' };
  const id: string = __normalizeCommandId(safeCommand.id);
  const status: string = typeof safeCommand.status === 'string' && safeCommand.status.length > 0 ? safeCommand.status : 'tracked';
  const updatedAt: string = typeof safeCommand.updatedAt === 'string' && safeCommand.updatedAt.length > 0 ? safeCommand.updatedAt : __deriveTimestamp(id, 0);

  const card: Card = { id: id, status: status, updatedAt: updatedAt };

  const run: TrackRun = {
    id: 'run-' + id,
    commandId: id,
    status: status,
    cardId: id,
    updatedAt: updatedAt,
  };

  __trackRuns.push(run);

  return card;
}

/**
 * List the trailing tracking runs for a given card identifier.
 *
 * Returns the most recent runs first, capped by the optional limit. When no
 * runs exist for the identifier an empty array is returned.
 *
 * @param id - the card identifier whose runs should be listed
 * @param limit - optional maximum number of runs to return
 * @returns a promise resolving to the matching track runs
 */
// req-13
// req-2
async function listTrackRuns(id: string, limit?: number): Promise<TrackRun[]> {
  const targetId: string = __normalizeCommandId(id);
  const matches: TrackRun[] = [];
  for (let i = 0; i < __trackRuns.length; i++) {
    const run: TrackRun = __trackRuns[i];
    if (run.commandId === targetId) {
      matches.push(run);
    }
  }
  matches.reverse();
  if (typeof limit === 'number' && limit >= 0 && limit < matches.length) {
    return matches.slice(0, limit);
  }
  return matches;
}
export { runTrack, listTrackRuns };

