import { renderPage, getFeaturedBouquets, renderTrustSignals, getBouquets, filterBouquets, sortBouquets, selectBouquetSize, getDeliveryZones } from "../generated/render-page.ts";
import { checkSameDayEligibility, getOccasionSections, submitBespokeEnquiry, formatGbpPrice, renderResponsiveLayout } from "../generated/check-same-day-eligibility.ts";
import { runWebMarketing, listWebMarketingRuns } from "../domain/web-marketing.ts";
import { runShow, listShowRuns } from "./show.ts";
type UpdateCommand = {
  kind: string;
  id: string;
  status: string;
  updatedAt: string;
  payload?: Record<string, unknown>;
};

type Customer = {
  id: string;
  status: string;
  updatedAt: string;
};

type UpdateRun = {
  id: string;
  command: string;
  entity: string;
  status: string;
  startedAt: string;
  finishedAt: string;
};

const runStore: UpdateRun[] = [];
const customerStore: Customer[] = [];

function deterministicSuffix(id: string): string {
  let hash = 0;
  for (let i = 0; i < id.length; i += 1) {
    hash = (hash * 31 + id.charCodeAt(i)) % 1000000007;
  }
  return hash.toString(36).padStart(6, "0");
}

function normalizeStatus(status: string): string {
  if (status === "active" || status === "inactive") {
    return status;
  }
  return "active";
}

/**
 * Applies an update command to a Customer entity and records the run.
 * // req-1
 */
async function runUpdate(command: UpdateCommand): Promise<Customer> {
  const id: string = command.id;
  const entity: Customer = {
    id: id,
    status: normalizeStatus(command.status),
    updatedAt: command.updatedAt,
  };
  let found = false;
  for (let i = 0; i < customerStore.length; i += 1) {
    if (customerStore[i].id === id) {
      customerStore[i] = entity;
      found = true;
      break;
    }
  }
  if (!found) {
    customerStore.push(entity);
  }
  const run: UpdateRun = {
    id: "urun-" + deterministicSuffix(id + command.updatedAt),
    command: command.kind,
    entity: id,
    status: "completed",
    startedAt: command.updatedAt,
    finishedAt: command.updatedAt,
  };
  runStore.push(run);
  return entity;
}

/**
 * Lists recorded update runs for a given customer id.
 * // req-1
 */
async function listUpdateRuns(id: string, limit?: number): Promise<UpdateRun[]> {
  const matches: UpdateRun[] = [];
  for (let i = 0; i < runStore.length; i += 1) {
    if (runStore[i].entity === id) {
      matches.push(runStore[i]);
    }
  }
  const effectiveLimit: number = typeof limit === "number" && limit >= 0 ? limit : matches.length;
  return matches.slice(0, effectiveLimit);
}
export { runUpdate, listUpdateRuns };

