  deliveryPostcode: string;
  deliveryDate: string;
  budgetRange: string;
  occasion: string;
  cardMessage: string;
  bouquetSize?: string;
};

type FieldError = {
  field: string;
  message: string;
};

type ValidationResult = {
  valid: boolean;
  errors: FieldError[];
  normalized: {
    senderName: string;
    recipientName: string;
    deliveryPostcode: string;
    deliveryDate: string;
    budgetRange: string;
    occasion: string;
    cardMessage: string;
    bouquetSize: string;
  };
};

type DeliveryZone = {
  name: string;
  prefixes: string[];
  fee: number;
  cutoff: string;
};

const BESPOKE_ZONES: DeliveryZone[] = [
  { name: 'Central', prefixes: ['EC', 'WC', 'E1', 'N1', 'SE1'], fee: 4.99, cutoff: '13:00' },
  { name: 'North', prefixes: ['N', 'NW', 'EN'], fee: 6.5, cutoff: '12:00' },
  { name: 'South', prefixes: ['SE', 'SW', 'CR', 'BR'], fee: 6.5, cutoff: '12:00' },
  { name: 'West', prefixes: ['W', 'TW', 'UB', 'HA'], fee: 7.25, cutoff: '11:30' },
  { name: 'East', prefixes: ['E', 'IG', 'RM', 'DA'], fee: 7.25, cutoff: '11:30' }
];

/**
 * Normalize a raw postcode for zone matching: uppercase, strip whitespace,
 * and remove an optional trailing space before the inward code.
 * @param raw - the postcode exactly as entered by the visitor.
 * @returns the canonical uppercase postcode with internal spaces removed.
 */
function normalizeBespokePostcode(raw: string): string {
  return String(raw).toUpperCase().replace(/\s+/g, '');
}

/**
 * Match a normalized postcode to its served delivery zone.
 * @param normalized - the uppercase, whitespace-free postcode.
 * @returns the matching zone, or null when no zone prefix matches.
 */
function matchBespokeZone(normalized: string): DeliveryZone | null {
  let best: DeliveryZone | null = null;
  let bestPrefixLength: number = 0;
  for (let i: number = 0; i < BESPOKE_ZONES.length; i += 1) {
    const zone: DeliveryZone = BESPOKE_ZONES[i];
    for (let j: number = 0; j < zone.prefixes.length; j += 1) {
      const prefix: string = zone.prefixes[j].toUpperCase().replace(/\s+/g, '');
      if (prefix.length > 0 && normalized.indexOf(prefix) === 0) {
        if (prefix.length > bestPrefixLength) {
          bestPrefixLength = prefix.length;
          best = zone;
        }
      }
    }
  }
  return best;
}

/**
 * Determine whether a delivery date string denotes a day strictly after `today`.
 * Accepts ISO `YYYY-MM-DD` dates. A date equal to today is rejected.
 * @param deliveryDate - the visitor's chosen delivery date (YYYY-MM-DD).
 * @param today - the reference date (YYYY-MM-DD) used as the lower bound.
 * @returns true when the date is parseable and strictly in the future.
 */
function isBespokeDateFuture(deliveryDate: string, today: string): boolean {
  const datePattern: RegExp = /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/;
  if (!datePattern.test(deliveryDate)) {
    return false;
  }
  const parsed: number = Date.parse(deliveryDate + 'T00:00:00Z');
  const todayParsed: number = Date.parse(today + 'T00:00:00Z');
  if (isNaN(parsed) || isNaN(todayParsed)) {
    return false;
  }
  return parsed > todayParsed;
}

/**
 * Validate a bespoke-order enquiry: every required field, the postcode zone
 * match, a future delivery date, and the 250-character card cap. Returns the
 * field-level errors plus the normalized values for submission.
 * @param input - the raw enquiry form payload.
 * @returns the validation outcome with per-field errors and normalized values.
 */
// req-11
// req-12
// req-13
function validateBespokeEnquiry(input: BespokeEnquiryInput): ValidationResult {
  const errors: FieldError[] = [];
  const senderName: string = String(input && input.senderName ? input.senderName : '').trim();
  const recipientName: string = String(input && input.recipientName ? input.recipientName : '').trim();
  const rawPostcode: string = String(input && input.deliveryPostcode ? input.deliveryPostcode : '').trim();
  const deliveryDate: string = String(input && input.deliveryDate ? input.deliveryDate : '').trim();
  const budgetRange: string = String(input && input.budgetRange ? input.budgetRange : '').trim();
  const occasion: string = String(input && input.occasion ? input.occasion : '').trim();
  const cardMessage: string = String(input && input.cardMessage ? input.cardMessage : '');
  const bouquetSize: string = String(input && input.bouquetSize ? input.bouquetSize : '').trim();
  const normalizedPostcode: string = normalizeBespokePostcode(rawPostcode);

  if (senderName.length === 0) {
    errors.push({ field: 'senderName', message: 'Please tell us your name.' });
  }
  if (recipientName.length === 0) {
    errors.push({ field: 'recipientName', message: "Please tell us the recipient's name." });
  }
  if (rawPostcode.length === 0) {
    errors.push({ field: 'deliveryPostcode', message: 'Please enter a delivery postcode.' });
  } else if (matchBespokeZone(normalizedPostcode) === null) {
    errors.push({
      field: 'deliveryPostcode',
      message: 'Sorry, that postcode is not in one of our served zones.'
    });
  }
  if (deliveryDate.length === 0) {
    errors.push({ field: 'deliveryDate', message: 'Please choose a delivery date.' });
  } else {
    const today: string = new Date().toISOString().slice(0, 10);
    if (!isBespokeDateFuture(deliveryDate, today)) {
      errors.push({ field: 'deliveryDate', message: 'Please choose a delivery date in the future.' });
    }
  }
  if (budgetRange.length === 0) {
    errors.push({ field: 'budgetRange', message: 'Please choose a budget range.' });
  }
  if (occasion.length === 0) {
    errors.push({ field: 'occasion', message: 'Please choose an occasion.' });
  }
  if (cardMessage.trim().length === 0) {
    errors.push({ field: 'cardMessage', message: 'Please add a message for the card.' });
  } else if (cardMessage.length > 250) {
    errors.push({ field: 'cardMessage', message: 'Card messages can be at most 250 characters.' });
  }

  return {
    valid: errors.length === 0,
    errors: errors,
    normalized: {
      senderName: senderName,
      recipientName: recipientName,
      deliveryPostcode: normalizedPostcode,
      deliveryDate: deliveryDate,
      budgetRange: budgetRange,
      occasion: occasion,
      cardMessage: cardMessage,
      bouquetSize: bouquetSize
    }
  };
}
